package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import com.lianxibu.site.repository.jobs.*;
import java.time.*;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import org.springframework.transaction.TransactionDefinition;
import org.springframework.transaction.support.TransactionTemplate;

/** Exact native initial intent provider, fictional scope only, no INPUT/body/attempt/model authority. */
class InitialReportIntentTest {
 GenerationJdbcStoreTest f;JdbcInitialReportIntent store;final LocalDate day=LocalDate.parse("2026-01-01");
 GenerationJdbcStoreTest fixture(){return new GenerationJdbcStoreTest();}
 @BeforeEach void setup(){f=fixture();f.fixture();if(f.source instanceof org.h2.jdbcx.JdbcDataSource local)local.setURL(local.getURL()+";INIT=SET TIME ZONE 'UTC'");f.jdbc.execute("ALTER TABLE jobs ADD COLUMN result_hash BINARY(32)");f.jdbc.execute("ALTER TABLE jobs ADD COLUMN report_mode VARCHAR(16)");f.clock=Clock.fixed(Instant.parse("2026-01-01T20:00:00.123456Z"),ZoneOffset.UTC);store=new JdbcInitialReportIntent(f.source);}
 JdbcInitialReportIntent.Scope scope(){return new JdbcInitialReportIntent.Scope("report:daily:"+day,"daily_report",day);}
 <T>T rr(java.util.function.Supplier<T> run){var tx=new TransactionTemplate(new DataSourceTransactionManager(f.source));tx.setReadOnly(true);tx.setIsolationLevel(TransactionDefinition.ISOLATION_REPEATABLE_READ);return tx.execute(s->run.get());}
 JdbcInitialReportIntent.Initial ensure(){return ReportOriginalCompletionTest.utc(()->f.writes.execute(new SharedWriteExecutor.ActionContext("fictional-initial-native","fictional-initial-native",null),k->null,a->store.ensureInWriter(scope(),f.clock.instant())));}
 @Test void MissingInitialCreatesOnlyStableIntentAndRepeatedNaturalKeyNeverCreatesBudget(){assertNull(rr(()->store.read(scope())));var first=ensure();assertEquals(1,first.generation());assertEquals("waiting_input",first.state());assertEquals(first,rr(()->store.read(scope())));assertEquals(first,ensure());assertEquals(1L,f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs",Long.class));assertEquals(0L,f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs WHERE record_kind IN ('logical_task','ai_attempt','snapshot_part')",Long.class));}
 @Test void LaterGenerationsNeverReplaceExactInitialNaturalResource(){var first=ensure();ReportOriginalCompletionTest.utc(()->f.writes.execute(new SharedWriteExecutor.ActionContext("fictional-later-intent","fictional-later-intent",null),k->null,a->new JdbcJobRecords(f.source).ensureIntent(new JdbcJobRecords.Intent(JdbcFrozenInputs.stableId("intent",scope().logicalKey()+":2"),scope().logicalKey(),2,scope().type(),day),f.clock.instant())));assertEquals(first,rr(()->store.read(scope())));assertEquals(first,ensure());assertEquals(2L,f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs",Long.class));}
 @Test void WriterFailureRollsBackNewInitialAndWrongRoleOrIdentityIsRejected(){assertThrows(RuntimeException.class,()->ReportOriginalCompletionTest.utc(()->f.writes.execute(new SharedWriteExecutor.ActionContext("fictional-initial-rollback","fictional-initial-rollback",null),k->null,a->{store.ensureInWriter(scope(),f.clock.instant());throw new IllegalStateException("fictional rollback");})));assertNull(rr(()->store.read(scope())));var first=ensure();f.jdbc.update("UPDATE jobs SET record_kind='unknown' WHERE id=?",first.id());assertThrows(RuntimeException.class,()->rr(()->store.read(scope())));setup();first=ensure();f.jdbc.update("UPDATE jobs SET record_identity_hash=? WHERE id=?",new byte[32],first.id());assertThrows(RuntimeException.class,()->rr(()->store.read(scope())));}
 @Test void ExistingPreparedInitialAcceptsLaterCutoffButNeverFutureOrUnknownNativeState(){var first=ensure();Instant cutoff=day.plusDays(1).atTime(5,0).atZone(ZoneId.of("Asia/Shanghai")).toInstant();ReportOriginalCompletionTest.utc(()->{f.jdbc.update("UPDATE jobs SET state='no_input',input_state='no_input',coverage_state='no_input',input_cutoff_at=?,updated_at=? WHERE id=?",java.sql.Timestamp.from(cutoff),java.sql.Timestamp.from(cutoff.plusSeconds(1)),first.id());return true;});var observed=rr(()->store.read(scope()));assertEquals(cutoff,observed.cutoff());assertTrue(observed.createdAt().isBefore(cutoff));assertEquals(observed,ensure());f.jdbc.update("UPDATE jobs SET input_state='unknown' WHERE id=?",first.id());assertThrows(RuntimeException.class,()->rr(()->store.read(scope())));}
 @Test void ConstructorIsColdAndExactBorrowedWriterReadModesCannotBeBypassed(){var source=mock(javax.sql.DataSource.class);new JdbcInitialReportIntent(source);verifyNoInteractions(source);assertThrows(RuntimeException.class,()->store.read(scope()));assertThrows(RuntimeException.class,()->store.ensureInWriter(scope(),f.clock.instant()));assertThrows(RuntimeException.class,()->rr(()->store.ensureInWriter(scope(),f.clock.instant())));assertThrows(RuntimeException.class,()->new JdbcInitialReportIntent.Scope("report:weekly:"+day,"weekly_report",day));assertThrows(RuntimeException.class,()->new JdbcInitialReportIntent.Scope("report:monthly:"+day,"monthly_report",day));}
}
